1: // @effect-diagnostics anyUnknownInErrorContext:off -- the ConfigProvider layer's failure channel is unknown in effect 4.1.2; the stack entry cannot narrow what it does not handle.
2: 
3: import * as Cloudflare from "@alchemy.run/cloudflare";
4: import { SurveyBeatApi } from "@surveybeat/api";
5: import { Database, MainWorker, ProductionEmail, SiteWorker, SubmissionWorker } from "@surveybeat/cloudflare";
6: import * as Alchemy from "alchemy";
7: import * as Secrets from "alchemy/Secrets";
8: import { Stack } from "alchemy/Stack";
9: import * as ConfigProvider from "effect/ConfigProvider";
10: import * as Effect from "effect/Effect";
11: import { readAllowlistForStage } from "./orgCreationAllowlist.ts";
12: 
13: export default Alchemy.Stack(
14:   "Surveybeat",
15:   {
16:     providers: Cloudflare.providers(),
17:     state: Cloudflare.state(),
18: 
19:     secrets: ({ stage }) => [
20:       Secrets.DotEnv(),
21:       Secrets.ProcessEnv(),
22:       ConfigProvider.layerAdd(
23:         ConfigProvider.fromEnv({ env: { ORG_CREATION_ALLOWLIST: readAllowlistForStage(stage) } }),
24:         { asPrimary: true },
25:       ),
26:     ],
27:   },
28:   Effect.gen(function* () {
29:     const { stage } = yield* Stack;
30: 
31:     if ((stage === "production" || stage === "staging") && "organizations" in SurveyBeatApi.groups) {
32:       throw new Error(
33:         "Deploy guard failed: unauthenticated OrganizationsApiGroup must not be registered in staging or production.",
34:       );
35:     }
36: 
37:     const database = yield* Database;
38:     const main = yield* MainWorker;
39:     const submission = yield* SubmissionWorker;
40:     const site = yield* SiteWorker;
41: 
42:     const sending = yield* ProductionEmail;
43: 
44:     return {
45:       databaseId: database.databaseId,
46:       mainUrl: main.url.as<string>(),
47:       submissionUrl: submission.url.as<string>(),
48:       siteUrl: site.url.as<string>(),
49:       ...(sending === undefined ? {} : { sendingDomainEnabled: sending.enabled }),
50:     };
51:   }),
52: );

