5: import * as Schema from "effect/Schema";
6: 
7: const Flag = Schema.optional(Schema.NullOr(Schema.Boolean));
8: 
9: const WorkerSettings = Schema.Struct({
10:   id: Schema.String,
11:   name: Schema.optional(Schema.String),
12:   tags: Schema.optional(Schema.NullOr(Schema.Array(Schema.String))),
13:   logpush: Flag,
14:   tail_consumers: Schema.optional(Schema.NullOr(Schema.Array(Schema.Unknown))),
15:   observability: Schema.optional(
16:     Schema.NullOr(
17:       Schema.Struct({
18:         enabled: Flag,
19:         logs: Schema.optional(
20:           Schema.NullOr(Schema.Struct({ enabled: Flag, invocation_logs: Flag, persist: Flag })),
21:         ),
22:         traces: Schema.optional(Schema.NullOr(Schema.Struct({ enabled: Flag, persist: Flag }))),
23:       }),
24:     ),
25:   ),
26: });
27: 
28: export type WorkerSettings = typeof WorkerSettings.Type;
29: 
30: const Page = Schema.Struct({
31:   result: Schema.Array(WorkerSettings),
32:   result_info: Schema.optional(Schema.Struct({ total_pages: Schema.optional(Schema.Finite) })),
33: });
34: 
35: const One = Schema.Struct({ result: WorkerSettings });
36: 
37: export const findViolations = (worker: WorkerSettings): string[] => {
38:   const observability = worker.observability;
39:   const logs = observability?.logs;
40:   const traces = observability?.traces;
41:   const found: string[] = [];
42: 
43:   if (observability?.enabled === true) {
44:     found.push("observability.enabled is on");
45:   }
46: 
47:   if (logs?.enabled === true) {
48:     found.push("observability.logs.enabled is on");
49:   }
50: 
51:   if (logs?.enabled === true && logs.invocation_logs === true) {
52:     found.push("observability.logs.invocation_logs is on");
53:   }
54: 
55:   if (logs?.enabled === true && logs.persist === true) {
56:     found.push("observability.logs.persist is on");
57:   }
58: 
59:   if (traces?.enabled === true) {
60:     found.push("observability.traces.enabled is on");
61:   }
62: 
63:   if (traces?.enabled === true && traces.persist === true) {
64:     found.push("observability.traces.persist is on");
65:   }
66: 
67:   if (worker.logpush === true) {
68:     found.push("logpush is on");
69:   }
70: 
71:   if ((worker.tail_consumers?.length ?? 0) > 0) {
72:     found.push("tail consumers are attached");
73:   }
74: 
75:   return found;
76: };
77: 
78: const api = "https://api.cloudflare.com/client/v4";
79: 
80: const get = async (path: string, token: string): Promise<unknown> => {
81:   const response = await fetch(`${api}${path}`, { headers: { authorization: `Bearer ${token}` } });
82: 
83:   if (!response.ok) {
84:     throw new Error(`GET ${path} failed with HTTP ${response.status}`);
85:   }
86: 
87:   return await response.json();
88: };
89: 
90: export const findWorker = async (
91:   accountId: string,
92:   token: string,
93:   stage: string,
94:   logicalId: string,
95: ): Promise<WorkerSettings> => {
96:   const wanted = ["alchemy:stack:Surveybeat", `alchemy:stage:${stage}`, `alchemy:id:${logicalId}`];
97: 
98:   for (let page = 1; ; page++) {
99:     const body = Schema.decodeUnknownSync(Page)(
100:       await get(`/accounts/${accountId}/workers/workers?per_page=100&page=${page}`, token),
101:     );
102: 
103:     const match = body.result.find((worker) => wanted.every((tag) => worker.tags?.includes(tag)));
104: 
105:     if (match !== undefined) {
106:       const detail = await get(`/accounts/${accountId}/workers/workers/${match.id}`, token);
107: 
108:       return Schema.decodeUnknownSync(One)(detail).result;
109:     }
110: 
111:     if (page >= (body.result_info?.total_pages ?? 1)) {
112:       throw new Error(`No ${logicalId} Worker found for stage ${stage}`);
113:     }
114:   }
115: };
116: 
117: const main = async (): Promise<number> => {
118:   const stageFlag = process.argv.indexOf("--stage");
119:   const stage = stageFlag === -1 ? undefined : process.argv[stageFlag + 1];
120:   const token = process.env.CLOUDFLARE_API_TOKEN;
121:   const accountId = process.env.CLOUDFLARE_ACCOUNT_ID;
122: 
123:   if (stage === undefined || token === undefined || accountId === undefined) {
124:     console.error(
125:       "Usage: check-observability.ts --stage <stage> (needs CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID)",
126:     );
127: 
128:     return 2;
129:   }
130: 
131:   const worker = await findWorker(accountId, token, stage, "Submission");
132:   console.log(
133:     JSON.stringify(
134:       {
135:         worker: worker.name ?? worker.id,
136:         observability: worker.observability,
137:         logpush: worker.logpush,
138:         tail_consumers: worker.tail_consumers,
139:       },
140:       null,
141:       2,
142:     ),
143:   );
144:   const violations = findViolations(worker);
145: 
146:   if (violations.length > 0) {
147:     for (const violation of violations) {
148:       console.error(`FAIL: ${violation}`);
149:     }
150: 
151:     return 1;
152:   }
153: 
154:   console.log("OK: every log channel is off and no tail consumer is attached");
155: 
156:   return 0;
157: };
158: 
159: if (import.meta.main) {
160:   process.exitCode = await main();
161: }

