90: const SURVEYBEAT_AUTH_PATHS = new Set([
91:   "/auth/login",
92:   "/auth/email-code",
93:   "/auth/email-code/verify",
94:   "/auth/logout",
95:   "/auth/session",
96:   "/auth/organization",
