100: export default class MainWorker extends Cloudflare.Worker<MainWorker>()(
101:   "Main",
102:   Effect.gen(function* () {
103:     const stack = yield* Stack;
104:     const hostname = hostnameFor(stack.stage, "app");
105:     const domain = mainWorkerDomainFor(stack.stage);
106: 
107:     return {
108:       main: import.meta.url,
109:       assets: mainWorkerAssets(stack.stage),
110:       env: {
111:         ...(yield* authBindings),
112:         OPENROUTER_API_KEY: Config.Redacted("OPENROUTER_API_KEY").pipe(Config.withDefault(Redacted.make(""))),
113:         ...(hostname === undefined ? {} : { APP_ORIGIN: `https://${hostname}` }),
114:       },
115:       ...(domain === undefined ? {} : { domain }),
116:     };
117:   }),
118:   Effect.gen(function* () {
119:     const organizations = yield* Organization;
120:     const jobs = yield* Jobs;
121:     const jobsDlq = yield* JobsDlq;
122: 
123:     yield* Cloudflare.Queues.consumeQueueMessages<JobMessage>(
124:       jobs,
125:       { batchSize: 10, maxRetries: 3, deadLetterQueue: jobsDlq },
126:       (stream) => Stream.runForEach(stream, () => Effect.log("JOB_PROCESSED")),
127:     );
128: 
129:     yield* Cloudflare.Queues.consumeQueueMessages<JobMessage>(jobsDlq, (stream) =>
130:       Stream.runForEach(stream, () => Effect.logError("JOB_DEAD_LETTERED")),
131:     );
132: 
133:     const { stage } = yield* Stack;
134:     const database = yield* Cloudflare.D1.QueryDatabase(yield* Database);
135:     const emailQueue = yield* EmailQueue;
136:     const emailDlq = yield* EmailQueueDlq;
137:     const sendClient = sendsRealEmail(stage) ? yield* Cloudflare.Email.Send(yield* SendEmail) : undefined;
138: 
139:     const signInEmail =
140:       sendClient === undefined
141:         ? yield* capturingEmailSender(database)
142:         : yield* cloudflareEmailSender(sendClient);
143: 
144:     const authInstance = yield* BetterAuth({
145:       ...authOptions(signInCodeDelivery(signInEmail.send)),
146:       id: "Auth",
147:       migrate: false,
148:     });
149: 
150:     yield* Cloudflare.Queues.consumeQueueMessages(
151:       emailQueue,
152:       { batchSize: 10, maxRetries: 10, deadLetterQueue: emailDlq },
153:       (stream) =>
154:         Effect.gen(function* () {
155:           const sender =
156:             sendClient === undefined
157:               ? yield* capturingEmailSender(database)
158:               : yield* cloudflareEmailSender(sendClient);
159: 
160:           yield* Stream.runForEach(stream, (message) =>
161:             handleSendMessage(organizations, database, message),
162:           ).pipe(
163:             Effect.provideService(EmailSender, sender),
164:             Effect.provide(EmailTemplatesLive.pipe(Layer.provide(InvitationTokensLive))),
165:           );
166:         }),
167:     );
168:     yield* Cloudflare.Queues.consumeQueueMessages(emailDlq, (stream) =>
169:       Stream.runForEach(stream, (message) => handleDeadLetter(organizations, message)),
170:     );
171: 
172:     if (sendsRealEmail(stage)) {
173:       yield* Cloudflare.Queues.consumeQueueMessages(
174:         yield* EmailEvents,
175:         { batchSize: 10, maxRetries: 5 },
176:         (stream) =>
177:           Stream.runForEach(stream, (message) => handleDeliveryEvent(organizations, database, message)),
178:       );
179:     }
180: 
181:     const settings = authSettings;
182:     const people = durableObjectPeople(organizations);
183:     const directory = durableObjectDirectory(organizations);
184:     const pulses = durableObjectPulses(organizations);
185:     const rounds = durableObjectRounds(organizations);
186:     const actions = durableObjectActions(organizations);
187:     const notes = durableObjectNotes(organizations);
188: 
189:     yield* Cloudflare.Workers.cron("0 0 * * *", () =>
190:       Effect.gen(function* () {
191:         const day = Math.floor((yield* Clock.currentTimeMillis) / 86_400_000);
192: 
193:         const counted = yield* database
194:           .prepare("SELECT COUNT(*) AS total FROM organization_index")
195:           .all<{ total: number }>();
196: 
197:         const window = repairWindow(counted.results[0]?.total ?? 0, day, REPAIR_PAGE_SIZE);
198: 
199:         const orgs = yield* database
200:           .prepare("SELECT organization_id FROM organization_index ORDER BY organization_id LIMIT ? OFFSET ?")
201:           .bind(window.limit, window.offset)
202:           .all<{ organization_id: string }>();
203: 
204:         for (const row of orgs.results) {
205:           yield* organizations.getByName(row.organization_id).repairAlarm().pipe(Effect.orDie);
206:         }
207:       }),
208:     );
209: 
210:     const services = Effect.gen(function* () {
211:       const runtime = yield* Effect.context<RuntimeContext>();
212: 
213:       const sessions = betterAuthIdentityProvider({
214:         auth: yield* authInstance.auth,
215:         chosenOrganization: (sessionId) =>
216:           database
217:             .prepare("SELECT organization_id FROM auth_session_organization WHERE session_id = ?")
218:             .bind(sessionId)
219:             .all<{ organization_id: string }>()
220:             .pipe(
221:               Effect.map((result) =>
222:                 Option.map(Option.fromNullishOr(result.results[0]), (row) =>
223:                   OrganizationId.make(row.organization_id),
224:                 ),
225:               ),
226:               Effect.provideContext(runtime),
227:               Effect.mapError(() => new AuthUnavailable()),
228:             ),
229:         rememberOrganization: (sessionId, organizationId) =>
230:           database
231:             .prepare(
232:               `INSERT INTO auth_session_organization (session_id, organization_id) VALUES (?, ?)
233:                ON CONFLICT (session_id) DO UPDATE SET organization_id = excluded.organization_id`,
234:             )
235:             .bind(sessionId, organizationId)
236:             .run()
237:             .pipe(
238:               Effect.asVoid,
239:               Effect.provideContext(runtime),
240:               Effect.mapError(() => new AuthUnavailable()),
241:             ),
242:         deleteSession: (sessionId) =>
243:           database
244:             .prepare("DELETE FROM auth_session WHERE id = ?")
245:             .bind(sessionId)
246:             .run()
247:             .pipe(
248:               Effect.asVoid,
249:               Effect.provideContext(runtime),
250:               Effect.mapError(() => new AuthUnavailable()),
251:             ),
252:       });
253: 
254:       return Context.make(SessionIdentityProvider, sessions).pipe(
255:         Context.add(PeopleIndex, yield* d1PeopleIndex(database)),
256:         Context.add(OrganizationPeople, people),
257:         Context.add(OrganizationDirectory, directory),
258:         Context.add(OrganizationPulses, pulses),
259:         Context.add(OrganizationRounds, rounds),
260:         Context.add(OrganizationActions, actions),
261:         Context.add(OrganizationNotes, notes),
262:         Context.add(
263:           NewIds,
264:           NewIds.of({
265:             organizationId: Effect.sync(newOrganizationId),
266:             personId: Effect.sync(() => PersonId.make(randomHex32())),
267:             teamId: Effect.sync(() => TeamId.make(randomHex32())),
268:             membershipId: Effect.sync(() => MembershipId.make(randomHex32())),
269:             pulseId: Effect.sync(() => PulseId.make(randomHex32())),
270:             questionId: Effect.sync(() => QuestionId.make(randomHex32())),
271:           }),
272:         ),
273:       );
274:     });
275: 
276:     const auth = authHandlers({ allowlist: Effect.map(settings, ({ allowlist }) => allowlist), services });
277: 
278:     const api = yield* HttpRouter.toHttpEffect(
279:       HttpApiBuilder.layer(SurveyBeatApi).pipe(
280:         Layer.provide([
281:           auth,
282:           directoryHandlers(services),
283:           pulseHandlers(services),
284:           roundHandlers(services),
285:           actionHandlers(services),
286:           noteHandlers(services),
287:         ]),
288:         Layer.provide([Etag.layer, httpPlatformStub, Path.layer]),
289:       ),
290:     );
291: 
292:     const pages = pageRoutes(organizations, database);
293:     const testRoutes = isTestStage(stage) ? emailTestRoutes(organizations, database) : undefined;
294: 
295:     return {
296:       fetch: Effect.gen(function* () {
297:         const request = yield* HttpServerRequest;
298:         const path = request.url.split("?")[0] ?? "/";
299: 
300:         if (path === DELIVERY_PAGE_PATH || path === UNSUBSCRIBE_PAGE_PATH) {
301:           return yield* pages;
302:         }
303: 
304:         if (path.startsWith("/auth/") && !SURVEYBEAT_AUTH_PATHS.has(path)) {
305:           return yield* authInstance.fetch.pipe(Effect.provide(RuntimeContext.phantom));
306:         }
307: 
308:         if (isTestStage(stage)) {
309:           if (path === TEST_ROUTES && testRoutes) {
310:             return yield* testRoutes;
311:           }
312: 
313:           if (path === PEOPLE_TEST_ROUTE) {
314:             return yield* peopleTestRoutes(organizations, database);
315:           }
316: 
317:           if (path === PULSES_TEST_ROUTE) {
318:             return yield* pulseTestRoutes(organizations);
319:           }
320: 
321:           if (path === ROUNDS_TEST_ROUTE) {
322:             return yield* roundTestRoutes(organizations, database);
323:           }
324: 
325:           if (path === ROUND_DELIVERY_TEST_ROUTE) {
326:             return yield* roundDeliveryTestRoutes(organizations);
327:           }
328: 
329:           if (path === THEMES_TEST_ROUTE) {
330:             return yield* themesTestRoutes(organizations);
331:           }
332: 
333:           if (path === REVIEW_TEST_ROUTE) {
334:             return yield* reviewTestRoutes(organizations);
335:           }
336: 
337:           if (path === RESULT_RECOVERY_TEST_ROUTE) {
338:             return yield* resultRecoveryTestRoutes(organizations);
339:           }
340: 
341:           if (path === TEST_INVITATION_TEST_ROUTE) {
342:             return yield* testInvitationTestRoutes(organizations, database);
343:           }
344: 
345:           if (path === RESEND_EMAIL_TEST_ROUTE) {
346:             return yield* resendEmailTestRoutes(organizations, database);
347:           }
348: 
349:           if (path === FLOW_TEST_ROUTE) {
350:             return yield* flowTestRoutes(organizations);
351:           }
352:         }
353: 
354:         return yield* api;
355:       }).pipe(Effect.orDie),
356:     };
357:   }).pipe(
358:     Effect.provide(
359:       Layer.mergeAll(
360:         RuntimeContext.phantom,
361:         CloudflareD1(Database),
362:         Cloudflare.Queues.EventSourceLive,
363:         Cloudflare.D1.QueryDatabaseBinding,
364:         Cloudflare.Email.SendBinding,
365:         Cloudflare.Workers.CronEventSourceLive,
366:         OrganizationLive,
367:       ),
368:     ),
369:   ),
370: ) {}

