84:  */
85: export const retryingServerErrors = (
86:   send: () => Promise<Response>,
87:   retries = 2,
88:   firstWait: Duration.Input = "2 seconds",
89: ): Effect.Effect<Response> => {
90:   const attempt = Effect.promise(send);
91:   return attempt.pipe(
92:     Effect.flatMap((response) => (response.status >= 500 ? Effect.fail(response) : Effect.succeed(response))),
93:     Effect.retry({ schedule: Schedule.exponential(firstWait), times: retries }),
94:     Effect.catch((lastServerError: Response) => Effect.succeed(lastServerError)),
95:   );
96: };
