100:     retryingServerErrors(() =>
101:       fetch(`${api}/accounts/${account.accountId}/workers/observability/telemetry/query`, {
102:         method: "POST",
103:         headers: { authorization: `Bearer ${account.token}`, "content-type": "application/json" },
104:         body: JSON.stringify(queryBody(query)),
105:       }),
106:     ),
107:   );
108:   if (!response.ok) {
109:     throw new Error(`Observability query failed with HTTP ${response.status}: ${await response.text()}`);
110:   }
111:   return decodeEventCount(await response.json());
112: };
