26: /** At a 1% sample rate, 1000 requests all go unsampled with probability 0.99^1000 ≈ 4e-5. */
27: const REQUESTS = 1000;
28: const CONCURRENCY = 25;
29: const DEADLINE_MS = 10 * 60_000;
30: const POLL_MS = 20_000;
31: /** Once Main's canary shows, Submission's events from the same moment have had time to arrive too. */
32: const SETTLE_MS = 60_000;
33: 
34: const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
