39: /** Sends `count` requests, `CONCURRENCY` at a time. Returns how many got any HTTP response, by status. */
40: const send = async (count: number, request: () => Promise<Response>): Promise<Map<number, number>> => {
41:   const statuses = new Map<number, number>();
42:   let started = 0;
43:   const worker = async () => {
44:     while (started < count) {
45:       started++;
46:       try {
47:         const response = await request();
48:         await response.body?.cancel();
49:         statuses.set(response.status, (statuses.get(response.status) ?? 0) + 1);
50:       } catch {
51:         // Not delivered: counts against the total below.
52:       }
53:     }
54:   };
55:   await Promise.all(Array.from({ length: CONCURRENCY }, worker));
56:   return statuses;
57: };
