import { spawnSync } from "node:child_process";
import path from "node:path";

export type ComplianceBenchmark = "all_compliance" | "gdpr" | "soc2";

export type ComplianceOutput = "text" | "brief" | "json" | "md" | "csv";

export interface ComplianceOptions {
  readonly benchmark: ComplianceBenchmark;
  readonly output: ComplianceOutput;
  readonly stage?: string;
  readonly dryRun: boolean;
}

const VALID_BENCHMARKS = new Set<string>(["all_compliance", "gdpr", "soc2"]);

const VALID_OUTPUTS = new Set<string>(["text", "brief", "json", "md", "csv"]);

const MOD_LOCATION = path.resolve(import.meta.dirname, "../compliance");

const OBSERVABILITY_SCRIPT = path.resolve(import.meta.dirname, "./check-observability.ts");

const writeLine = (stream: NodeJS.WriteStream, line: string): void => {
  stream.write(`${line}\n`);
};

const readFlagValue = (args: ReadonlyArray<string>, index: number, flag: string): string => {
  const value = args[index + 1];

  if (value === undefined || value.startsWith("--")) {
    throw new Error(`${flag} requires a value`);
  }

  return value;
};

export const parseComplianceArgs = (args: ReadonlyArray<string>): ComplianceOptions => {
  let benchmark: ComplianceBenchmark = "all_compliance";
  let output: ComplianceOutput = "text";
  let stage: string | undefined;
  let dryRun = false;

  for (let index = 0; index < args.length; index++) {
    const arg = args[index];

    if (arg === "--benchmark") {
      const value = readFlagValue(args, index, "--benchmark");
      index++;

      if (value === "all_compliance" || value === "gdpr" || value === "soc2") {
        benchmark = value;
      } else {
        throw new Error(
          `Unknown benchmark "${value}". Expected one of: ${[...VALID_BENCHMARKS].join(", ")}`,
        );
      }
    } else if (arg === "--output") {
      const value = readFlagValue(args, index, "--output");
      index++;

      if (
        value === "text" ||
        value === "brief" ||
        value === "json" ||
        value === "md" ||
        value === "csv"
      ) {
        output = value;
      } else {
        throw new Error(`Unknown output "${value}". Expected one of: ${[...VALID_OUTPUTS].join(", ")}`);
      }
    } else if (arg === "--stage") {
      stage = readFlagValue(args, index, "--stage");
      index++;
    } else if (arg === "--dry-run") {
      dryRun = true;
    } else {
      throw new Error(`Unknown argument "${arg ?? ""}"`);
    }
  }

  return stage === undefined ? { benchmark, output, dryRun } : { benchmark, output, stage, dryRun };
};

export const buildPowerpipeArgs = (options: ComplianceOptions): ReadonlyArray<string> => [
  "benchmark",
  "run",
  "--mod-location",
  MOD_LOCATION,
  "--output",
  options.output,
  "--input=false",
  ...(options.dryRun ? ["--dry-run"] : []),
  options.benchmark,
];

const hasCommand = (command: string): boolean => {
  const result = spawnSync("which", [command], { stdio: "ignore" });

  return result.status === 0;
};

const ensureSteampipeService = (env: NodeJS.ProcessEnv): number => {
  const status = spawnSync("steampipe", ["service", "status"], { env, stdio: "ignore" });

  if (status.status === 0) {
    return 0;
  }

  const started = spawnSync("steampipe", ["service", "start"], { env, stdio: "inherit" });

  return started.status ?? 1;
};

const run = (): number => {
  let options: ComplianceOptions;

  try {
    options = parseComplianceArgs(process.argv.slice(2));
  } catch (error) {
    writeLine(process.stderr, error instanceof Error ? error.message : String(error));
    writeLine(
      process.stderr,
      "Usage: check-compliance.ts [--benchmark all_compliance|gdpr|soc2] [--output text|brief|json|md|csv] [--stage <stage>] [--dry-run]",
    );

    return 2;
  }

  if (!hasCommand("steampipe") || !hasCommand("powerpipe")) {
    writeLine(
      process.stderr,
      "Missing steampipe or powerpipe CLI. See infra/compliance/README.md for installation.",
    );

    return 2;
  }

  const env = process.env;

  if (!options.dryRun) {
    if (env["CLOUDFLARE_API_TOKEN"] === undefined || env["CLOUDFLARE_API_TOKEN"] === "") {
      writeLine(
        process.stderr,
        "CLOUDFLARE_API_TOKEN is unset; Steampipe will rely on ~/.steampipe/config/cloudflare.spc if configured.",
      );
    }

    const serviceExit = ensureSteampipeService(env);

    if (serviceExit !== 0) {
      return serviceExit;
    }
  }

  const ppResult = spawnSync("powerpipe", [...buildPowerpipeArgs(options)], {
    env,
    stdio: "inherit",
  });

  if (ppResult.status !== 0) {
    return ppResult.status ?? 1;
  }

  if (options.stage !== undefined && !options.dryRun) {
    const obsResult = spawnSync(process.execPath, [OBSERVABILITY_SCRIPT, "--stage", options.stage], {
      env,
      stdio: "inherit",
    });

    if (obsResult.status !== 0) {
      return obsResult.status ?? 1;
    }
  }

  return 0;
};

if (import.meta.main) {
  process.exitCode = run();
}

import { describe, expect, it } from "vitest";
import { buildPowerpipeArgs, parseComplianceArgs } from "./check-compliance.ts";

describe("parseComplianceArgs", () => {
  it("uses sensible defaults with no flags", () => {
    expect(parseComplianceArgs([])).toEqual({
      benchmark: "all_compliance",
      output: "text",
      dryRun: false,
    });
  });

  it("parses benchmark, output, stage, and dry-run flags", () => {
    expect(
      parseComplianceArgs(["--benchmark", "gdpr", "--output", "json", "--stage", "production", "--dry-run"]),
    ).toEqual({
      benchmark: "gdpr",
      output: "json",
      stage: "production",
      dryRun: true,
    });
  });

  it("rejects unknown benchmarks and flags", () => {
    expect(() => parseComplianceArgs(["--benchmark", "hipaa"])).toThrow(/Unknown benchmark/);
    expect(() => parseComplianceArgs(["--unknown"])).toThrow(/Unknown argument/);
  });
});

describe("buildPowerpipeArgs", () => {
  it("builds dry-run arguments pointing at infra/compliance", () => {
    const args = buildPowerpipeArgs({
      benchmark: "soc2",
      output: "md",
      dryRun: true,
    });

    expect(args).toContain("--dry-run");
    expect(args).toContain("soc2");
    expect(args).toContain("md");
    expect(args.some((arg) => arg.endsWith("/infra/compliance"))).toBe(true);
  });
});

